// F523 C8: the source text a runtime-components resolver compiles with `compileComponent` (an app would keep it in a
// database). It is StaticNode.tsx's text exactly; tests/server/recursive.chromium.test.ts checks they are equal.
export const rcSource: string = "// The built twin of `rcSource.ts` (same text, no imports so it compiles at any virtual path): a component that renders itself, static, one template macro.\ntype N = { id: string; kind: string; label: string; children?: N[] }\n\nexport default function StaticNode({ n }: { n: N }) {\n  if (n.kind === 'group')\n    return (\n      <section data-id={n.id}>\n        <h2>{n.label}</h2>\n        <div>\n          {(n.children ?? []).map((c) => (\n            <StaticNode key={c.id} n={c} />\n          ))}\n        </div>\n      </section>\n    )\n  return <p data-id={n.id}>{n.label}</p>\n}\n"
